import React, { useState } from "react";
import { ErrorBoundary } from "./ErrorBoundary";

function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("Intentional render error");
  return <p>Component rendered successfully.</p>;
}

export function App() {
  const [shouldThrow, setShouldThrow] = useState(false);

  return (
    <div style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <h1>ErrorBoundary Demo</h1>

      {/* Default fallback */}
      <ErrorBoundary onError={(err, info) => console.log("Logged:", err, info)}>
        <Bomb shouldThrow={shouldThrow} />
      </ErrorBoundary>

      {/* Custom fallback */}
      <ErrorBoundary
        fallback={(error, reset) => (
          <div>
            <p>Custom fallback: {error.message}</p>
            <button onClick={reset}>Retry</button>
          </div>
        )}
      >
        <Bomb shouldThrow={shouldThrow} />
      </ErrorBoundary>

      <button onClick={() => setShouldThrow((v) => !v)}>
        Toggle error
      </button>
    </div>
  );
}
EOF</parameter>
